import os

try:
    Import("env")
    project_dir = env.get("PROJECT_DIR")
except Exception:
    project_dir = os.path.dirname(os.path.abspath(__file__))

env_file = os.path.join(project_dir, ".env")
header_file = os.path.join(project_dir, "include", "env.h")

if os.path.exists(env_file):
    lines = [
        "// Auto-generated from .env by load_env.py\n",
        "// Do not edit this file directly. Edit .env instead.\n",
        "#pragma once\n\n"
    ]
    with open(env_file, "r") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            key, val = line.split("=", 1)
            key = key.strip()
            val = val.strip().strip("'\"")
            
            # Numeric identifiers without quotes (Channel, ID, Port)
            if (key.endswith("_CHANNEL") or key.endswith("_ID") or key.endswith("_PORT")) and val.isdigit():
                lines.append(f"#define ENV_{key} {val}\n")
            else:
                lines.append(f'#define ENV_{key} "{val}"\n')
                
    os.makedirs(os.path.join(project_dir, "include"), exist_ok=True)
    with open(header_file, "w") as f:
        f.writelines(lines)
    print(f"[load_env.py] Generated {header_file} from .env")
else:
    print(f"[load_env.py] Warning: .env not found at {env_file}")

